91	func TestCleanupScopedToOneServiceLeavesOthersUntouched(t *testing.T) {
92		router, st := testRouter(t)
93		seedCleanupInstances(t, router)
94	
95		code, out := cleanupRequest(t, router, "/api/v1/cleanup", map[string]any{
