138	func TestCleanupKeepsBoundaryAndReportsEmptyResult(t *testing.T) {
139		router, st := testRouter(t)
140		// heartbeat at(5) with timeout 5m puts the lost boundary exactly at(10).
141		registerInstance(t, router, map[string]any{
142			"service_name": "svc", "instance_id": "boundary", "healthy": true,
