149	
150		rec := doRequest(t, router, http.MethodPost,
151			"/api/v1/cleanup?evaluate_at="+at(10)+"&heartbeat_timeout=300", nil)
152		if rec.Code != http.StatusOK {
153			t.Fatalf("status = %d, want 200, body %s", rec.Code, rec.Body.String())
154		}
155		out := decodeBody(t, rec)
156		if out["removed"] != float64(0) {
157			t.Fatalf("removed = %v, want 0", out["removed"])
158		}
159		if list, ok := out["instances"].([]any); !ok || len(list) != 0 {
160			t.Fatalf("instances = %v, want empty list", out["instances"])
161		}
162		if !strings.Contains(rec.Body.String(), `"instances":[]`) {
163			t.Fatalf("instances must serialize as an empty array: %s", rec.Body.String())
164		}
165		for _, id := range []string{"boundary", "sick"} {
166			if _, found, err := st.GetInstance("svc", id); err != nil || !found {
167				t.Fatalf("svc/%s must survive: found=%v err=%v", id, found, err)
168			}
169		}
170	}
