172	func TestCleanupRejectsInvalidParametersWithoutDeleting(t *testing.T) {
173		router, st := testRouter(t)
174		seedCleanupInstances(t, router)
175	
176		targets := []string{
177			"/api/v1/cleanup",                                                               // missing evaluate_at and timeout
178			"/api/v1/cleanup?heartbeat_timeout=5m",                                          // missing evaluate_at
179			"/api/v1/cleanup?evaluate_at=not-a-time&heartbeat_timeout=5m",                   // bad evaluate_at
180			"/api/v1/cleanup?evaluate_at=" + at(10),                                         // missing heartbeat_timeout
181			"/api/v1/cleanup?evaluate_at=" + at(10) + "&heartbeat_timeout=0",                // zero timeout
182			"/api/v1/cleanup?evaluate_at=" + at(10) + "&heartbeat_timeout=-5",               // negative timeout
183			"/api/v1/cleanup?evaluate_at=" + at(10) + "&heartbeat_timeout=abc",              // bad timeout
184			"/api/v1/cleanup?evaluate_at=" + at(10) + "&heartbeat_timeout=5m&service_name=", // empty service_name
185		}
186		for _, target := range targets {
187			rec := doRequest(t, router, http.MethodPost, target, nil)
188			expectParameterError(t, rec)
189		}
190		// An explicit empty service_name in the JSON body is rejected as well.
191		rec := doRequest(t, router, http.MethodPost, "/api/v1/cleanup", map[string]any{
192			"service_name": "", "evaluate_at": at(10), "heartbeat_timeout": "5m",
193		})
194		expectParameterError(t, rec)
195	
196		// evaluate_at earlier than an instance heartbeat in the evaluated scope.
197		rec = doRequest(t, router, http.MethodPost,
198			"/api/v1/cleanup?evaluate_at="+at(4)+"&heartbeat_timeout=5m", nil)
199		expectParameterError(t, rec)
200	
201		// No rejected request may have deleted anything.
202		remaining, err := st.ListAllInstances()
203		if err != nil {
204			t.Fatalf("list: %v", err)
205		}
206		if len(remaining) != 5 {
207			t.Fatalf("remaining = %d, want all 5 records untouched", len(remaining))
208		}
209	}
