215			"weight": 1, "heartbeat_at": at(0),
216		})
217		// beta's heartbeat is later than the evaluation point, but beta is not
218		// part of the evaluated scope, so the request stays valid.
219		registerInstance(t, router, map[string]any{
220			"service_name": "beta", "instance_id": "i-1", "healthy": true,
221			"weight": 1, "heartbeat_at": at(30),
222		})
223	
224		code, out := cleanupRequest(t, router, "/api/v1/cleanup", map[string]any{
225			"service_name": "alpha", "evaluate_at": at(10), "heartbeat_timeout": "5m",
226		})
227		if code != http.StatusOK {
228			t.Fatalf("status = %d, want 200, body %v", code, out)
229		}
230		if out["removed"] != float64(1) {
231			t.Fatalf("removed = %v, want 1", out["removed"])
232		}
233		if _, found, err := st.GetInstance("beta", "i-1"); err != nil || !found {
234			t.Fatalf("beta/i-1 must be untouched: found=%v err=%v", found, err)
235		}
236	}
