1	// Package store owns the SQLite file and every write the service performs.
2	package store
3	
4	import (
5		"database/sql"
6		"errors"
7		"fmt"
8		"time"
9	
10		_ "modernc.org/sqlite"
11	)
12	
13	// ErrInstanceNotFound reports that a targeted instance does not exist.
14	var ErrInstanceNotFound = errors.New("instance not found")
15	
16	// Store wraps the SQLite handle so callers never touch database/sql directly.
17	type Store struct {
18		db *sql.DB
19	}
20	
21	// Instance is the current record of one registered service instance.
22	type Instance struct {
23		ServiceName string
24		InstanceID  string
25		Address     string
26		Port        int64
27		Healthy     bool
28		Weight      float64
29		HeartbeatAt time.Time
30	}
31	
32	// InstanceInput carries the fields callers provide on registration or update.
33	type InstanceInput struct {
34		ServiceName string
35		InstanceID  string
36		Address     string
37		Port        int64
38		Healthy     bool
39		Weight      float64
40		HeartbeatAt time.Time
41	}
42	
43	// HeartbeatTarget carries one heartbeat renewal in a batch: the existing
44	// instance identified by InstanceID gets only its HeartbeatAt replaced.
45	type HeartbeatTarget struct {
46		InstanceID  string
47		HeartbeatAt time.Time
48	}
49	
50	// WeightTarget carries one weight change in a batch: the existing instance
51	// identified by InstanceID gets only its Weight replaced.
52	type WeightTarget struct {
53		InstanceID string
54		Weight     float64
55	}
56	
57	// HealthTarget carries one health-state change in a batch: the existing
58	// instance identified by InstanceID gets only its Healthy flag replaced.
59	type HealthTarget struct {
60		InstanceID string
61		Healthy    bool
62	}
63	
64	// Open prepares the database file and the schema this service needs.
65	func Open(path string) (*Store, error) {
66		db, err := sql.Open("sqlite", path)
67		if err != nil {
68			return nil, fmt.Errorf("open sqlite: %w", err)
69		}
70		if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
71			db.Close()
72			return nil, fmt.Errorf("enable wal: %w", err)
73		}
74		if _, err := db.Exec(schema); err != nil {
75			db.Close()
76			return nil, fmt.Errorf("apply schema: %w", err)
77		}
78		if err := migrate(db); err != nil {
79			db.Close()
80			return nil, fmt.Errorf("migrate schema: %w", err)
81		}
82		return &Store{db: db}, nil
83	}
84	
85	// migrate upgrades database files created by earlier versions in place.
86	func migrate(db *sql.DB) error {
87		var count int
88		if err := db.QueryRow(
89			`SELECT COUNT(1) FROM pragma_table_info('service_instances') WHERE name = 'port'`).Scan(&count); err != nil {
90			return err
91		}
92		if count == 0 {
93			if _, err := db.Exec(`ALTER TABLE service_instances ADD COLUMN port INTEGER NOT NULL DEFAULT 0`); err != nil {
94				return err
95			}
96		}
97		return nil
98	}
99	
100	// Ping reports whether the storage layer is usable.
101	func (s *Store) Ping() error { return s.db.Ping() }
102	
103	// Close releases the database handle.
104	func (s *Store) Close() error { return s.db.Close() }
105	
106	// UpsertInstance inserts an instance record or overwrites the current record
107	// of the same (service name, instance id) pair.
108	func (s *Store) UpsertInstance(input InstanceInput) (Instance, error) {
109		heartbeat := input.HeartbeatAt.UTC().Format(time.RFC3339Nano)
110		_, err := s.db.Exec(`
111	INSERT INTO service_instances
112		(service_name, instance_id, address, port, healthy, weight, heartbeat_at)
113	VALUES (?, ?, ?, ?, ?, ?, ?)
114	ON CONFLICT(service_name, instance_id) DO UPDATE SET
115		address = excluded.address,
116		port = excluded.port,
117		healthy = excluded.healthy,
118		weight = excluded.weight,
119		heartbeat_at = excluded.heartbeat_at`,
120			input.ServiceName, input.InstanceID, input.Address, input.Port, input.Healthy, input.Weight, heartbeat)
121		if err != nil {
122			return Instance{}, err
123		}
124		return Instance{
125			ServiceName: input.ServiceName,
126			InstanceID:  input.InstanceID,
127			Address:     input.Address,
128			Port:        input.Port,
129			Healthy:     input.Healthy,
130			Weight:      input.Weight,
131			HeartbeatAt: input.HeartbeatAt.UTC(),
132		}, nil
133	}
134	
135	// UpsertInstances inserts or overwrites several instances of one service in a
136	// single transaction. Every input shares the same service name and instance
137	// ids are expected to be unique within the batch; stored records are returned
138	// in request order. Any failure rolls the whole batch back without leaving
139	// partial updates.
140	func (s *Store) UpsertInstances(inputs []InstanceInput) ([]Instance, error) {
141		tx, err := s.db.Begin()
142		if err != nil {
143			return nil, err
144		}
145		defer tx.Rollback()
146	
147		statement, err := tx.Prepare(`
148	INSERT INTO service_instances
149		(service_name, instance_id, address, port, healthy, weight, heartbeat_at)
150	VALUES (?, ?, ?, ?, ?, ?, ?)
151	ON CONFLICT(service_name, instance_id) DO UPDATE SET
152		address = excluded.address,
153		port = excluded.port,
154		healthy = excluded.healthy,
155		weight = excluded.weight,
156		heartbeat_at = excluded.heartbeat_at`)
157		if err != nil {
158			return nil, err
159		}
160		defer statement.Close()
161	
162		for _, input := range inputs {
163			if _, err := statement.Exec(
164				input.ServiceName, input.InstanceID, input.Address, input.Port,
165				input.Healthy, input.Weight,
166				input.HeartbeatAt.UTC().Format(time.RFC3339Nano)); err != nil {
167				return nil, err
168			}
169		}
170	
171		instances := make([]Instance, 0, len(inputs))
172		for _, input := range inputs {
173			instances = append(instances, Instance{
174				ServiceName: input.ServiceName,
175				InstanceID:  input.InstanceID,
176				Address:     input.Address,
177				Port:        input.Port,
178				Healthy:     input.Healthy,
179				Weight:      input.Weight,
180				HeartbeatAt: input.HeartbeatAt.UTC(),
181			})
182		}
183	
184		if err := tx.Commit(); err != nil {
185			return nil, err
186		}
187		return instances, nil
188	}
189	
190	// GetInstance reads the current record of one instance.
191	func (s *Store) GetInstance(serviceName, instanceID string) (Instance, bool, error) {
192		row := s.db.QueryRow(`
193	SELECT service_name, instance_id, address, port, healthy, weight, heartbeat_at
194	FROM service_instances
195	WHERE service_name = ? AND instance_id = ?`, serviceName, instanceID)
196		instance, err := scanInstance(row)
197		if err == sql.ErrNoRows {
198			return Instance{}, false, nil
199		}
200		if err != nil {
201			return Instance{}, false, err
202		}
203		return instance, true, nil
204	}
205	
206	// ListInstances reads every current record belonging to one service. Other
207	// services are never touched or removed.
208	func (s *Store) ListInstances(serviceName string) ([]Instance, error) {
209		rows, err := s.db.Query(`
210	SELECT service_name, instance_id, address, port, healthy, weight, heartbeat_at
211	FROM service_instances
212	WHERE service_name = ?`, serviceName)
213		if err != nil {
214			return nil, err
215		}
216		defer rows.Close()
217	
218		instances := make([]Instance, 0)
219		for rows.Next() {
220			instance, err := scanInstance(rows)
221			if err != nil {
222				return nil, err
223			}
224			instances = append(instances, instance)
225		}
226		if err := rows.Err(); err != nil {
227			return nil, err
228		}
229		return instances, nil
230	}
231	
232	// ListAllInstances reads every current record across all services. It never
233	// creates, updates or deletes rows; callers aggregate the read-only snapshot
234	// themselves. Results are ordered by service name and then instance id so
235	// identical storage content yields identical output.
236	func (s *Store) ListAllInstances() ([]Instance, error) {
237		rows, err := s.db.Query(`
238	SELECT service_name, instance_id, address, port, healthy, weight, heartbeat_at
239	FROM service_instances
240	ORDER BY service_name ASC, instance_id ASC`)
241		if err != nil {
242			return nil, err
243		}
244		defer rows.Close()
245	
246		instances := make([]Instance, 0)
247		for rows.Next() {
248			instance, err := scanInstance(rows)
249			if err != nil {
250				return nil, err
251			}
252			instances = append(instances, instance)
253		}
254		if err := rows.Err(); err != nil {
255			return nil, err
256		}
257		return instances, nil
258	}
259	
260	// DeleteInstance removes one instance record and reports whether it existed.
261	func (s *Store) DeleteInstance(serviceName, instanceID string) (bool, error) {
262		result, err := s.db.Exec(`
263	DELETE FROM service_instances WHERE service_name = ? AND instance_id = ?`, serviceName, instanceID)
264		if err != nil {
265			return false, err
266		}
267		affected, err := result.RowsAffected()
268		if err != nil {
269			return false, err
270		}
271		return affected > 0, nil
272	}
273	
274	// InstanceKey identifies one instance record for a targeted write.
275	type InstanceKey struct {
276		ServiceName string
277		InstanceID  string
278	}
279	
280	// DeleteInstances removes the identified records in a single transaction.
281	// Any failure rolls the whole batch back, so a failed request never leaves
282	// partial deletions behind.
283	func (s *Store) DeleteInstances(keys []InstanceKey) error {
284		tx, err := s.db.Begin()
285		if err != nil {
286			return err
287		}
288		defer tx.Rollback()
289	
290		statement, err := tx.Prepare(`
291	DELETE FROM service_instances WHERE service_name = ? AND instance_id = ?`)
292		if err != nil {
293			return err
294		}
295		defer statement.Close()
296	
297		for _, key := range keys {
298			if _, err := statement.Exec(key.ServiceName, key.InstanceID); err != nil {
299				return err
300			}
301		}
302		return tx.Commit()
303	}
304	
305	// TouchHeartbeats replaces only heartbeat_at of the named service's
306	// instances. The whole batch runs in one transaction: when any target does
307	// not exist the transaction rolls back and ErrInstanceNotFound is returned
308	// without partial updates. Updated records are returned in request order.
309	func (s *Store) TouchHeartbeats(serviceName string, targets []HeartbeatTarget) ([]Instance, error) {
310		tx, err := s.db.Begin()
311		if err != nil {
312			return nil, err
313		}
314		defer tx.Rollback()
315	
316		statement, err := tx.Prepare(`
317	UPDATE service_instances SET heartbeat_at = ?
318	WHERE service_name = ? AND instance_id = ?`)
319		if err != nil {
320			return nil, err
321		}
322		defer statement.Close()
323	
324		for _, target := range targets {
325			result, err := statement.Exec(
326				target.HeartbeatAt.UTC().Format(time.RFC3339Nano), serviceName, target.InstanceID)
327			if err != nil {
328				return nil, err
329			}
330			affected, err := result.RowsAffected()
331			if err != nil {
332				return nil, err
333			}
334			if affected == 0 {
335				return nil, ErrInstanceNotFound
336			}
337		}
338	
339		updated := make([]Instance, 0, len(targets))
340		for _, target := range targets {
341			row := tx.QueryRow(`
342	SELECT service_name, instance_id, address, port, healthy, weight, heartbeat_at
343	FROM service_instances
344	WHERE service_name = ? AND instance_id = ?`, serviceName, target.InstanceID)
345			instance, err := scanInstance(row)
346			if err == sql.ErrNoRows {
347				return nil, ErrInstanceNotFound
348			}
349			if err != nil {
350				return nil, err
351			}
352			updated = append(updated, instance)
353		}
354	
355		if err := tx.Commit(); err != nil {
356			return nil, err
357		}
358		return updated, nil
359	}
