361	// UpdateWeights replaces only weight of the named service's instances. All
362	// targets must exist before any row is touched: the existence check runs
363	// inside the transaction and a missing target rolls the whole batch back
364	// with ErrInstanceNotFound. Updated records are returned in request order.
365	func (s *Store) UpdateWeights(serviceName string, targets []WeightTarget) ([]Instance, error) {
366		tx, err := s.db.Begin()
367		if err != nil {
368			return nil, err
369		}
370		defer tx.Rollback()
371	
372		countStatement, err := tx.Prepare(`
373	SELECT COUNT(1) FROM service_instances
374	WHERE service_name = ? AND instance_id = ?`)
375		if err != nil {
376			return nil, err
377		}
378		defer countStatement.Close()
379	
380		for _, target := range targets {
381			var count int
382			if err := countStatement.QueryRow(serviceName, target.InstanceID).Scan(&count); err != nil {
383				return nil, err
384			}
385			if count == 0 {
386				return nil, ErrInstanceNotFound
387			}
388		}
389	
390		updateStatement, err := tx.Prepare(`
391	UPDATE service_instances SET weight = ?
392	WHERE service_name = ? AND instance_id = ?`)
393		if err != nil {
394			return nil, err
395		}
396		defer updateStatement.Close()
397	
398		for _, target := range targets {
399			if _, err := updateStatement.Exec(target.Weight, serviceName, target.InstanceID); err != nil {
400				return nil, err
401			}
402		}
403	
404		updated := make([]Instance, 0, len(targets))
405		for _, target := range targets {
406			row := tx.QueryRow(`
407	SELECT service_name, instance_id, address, port, healthy, weight, heartbeat_at
408	FROM service_instances
409	WHERE service_name = ? AND instance_id = ?`, serviceName, target.InstanceID)
410			instance, err := scanInstance(row)
411			if err == sql.ErrNoRows {
412				return nil, ErrInstanceNotFound
413			}
414			if err != nil {
415				return nil, err
416			}
417			updated = append(updated, instance)
418		}
419	
420		if err := tx.Commit(); err != nil {
421			return nil, err
422		}
423		return updated, nil
424	}
425	
426	// UpdateHealth replaces only the healthy flag of the named service's
427	// instances. All targets must exist before any row is touched: the existence
428	// check runs inside the transaction and a missing target rolls the whole
429	// batch back with ErrInstanceNotFound. Address, port, weight, heartbeat_at,
430	// service name and instance id all keep their current values. Updated
431	// records are returned in request order.
432	func (s *Store) UpdateHealth(serviceName string, targets []HealthTarget) ([]Instance, error) {
433		tx, err := s.db.Begin()
434		if err != nil {
435			return nil, err
436		}
