460		if err != nil {
461			return nil, err
462		}
463		defer updateStatement.Close()
464	
465		for _, target := range targets {
466			if _, err := updateStatement.Exec(target.Healthy, serviceName, target.InstanceID); err != nil {
467				return nil, err
468			}
469		}
470	
471		updated := make([]Instance, 0, len(targets))
