540		// Invalid ports are rejected and change nothing.
541		rec = doRequest(t, router, http.MethodPost, "/api/v1/register", map[string]any{
542			"service_name": "svc", "instance_id": "i-3", "port": -1,
543			"weight": 1, "heartbeat_at": baseTime,
544		})
545		expectParameterError(t, rec)
546		if list, _ := st.ListInstances("svc"); len(list) != 2 {
547			t.Fatalf("invalid port changed storage: %d rows", len(list))
548		}
549	}
550	
551	func TestDiscoverBoundaryKeepsEqualAndEvictsStrictlyLater(t *testing.T) {
552		router, st := testRouter(t)
553		registerInstance(t, router, map[string]any{
554			"service_name": "svc", "instance_id": "edge", "healthy": true,
555			"weight": 1, "heartbeat_at": at(0),
556		})
557	
558		// Heartbeat exactly at heartbeat_at + timeout is still online.
559		target := "/api/v1/discover?service_name=svc&evaluate_at=" + at(10) + "&heartbeat_timeout=10m"
560		out := decodeBody(t, doRequest(t, router, http.MethodGet, target, nil))
561		if ids := instanceIDs(t, out); len(ids) != 1 || ids[0] != "edge" {
562			t.Fatalf("boundary ids = %v, want [edge]", ids)
563		}
564		if _, found, _ := st.GetInstance("svc", "edge"); !found {
565			t.Fatalf("boundary query deleted an online record")
566		}
567	
568		// One second past the boundary the instance is lost: excluded and deleted.
569		evaluate := time.Date(2026, 10, 1, 12, 10, 1, 0, time.UTC).Format(time.RFC3339)
570		target = "/api/v1/discover?service_name=svc&evaluate_at=" + evaluate + "&heartbeat_timeout=10m"
571		out = decodeBody(t, doRequest(t, router, http.MethodGet, target, nil))
572		if ids := instanceIDs(t, out); len(ids) != 0 {
573			t.Fatalf("past-boundary ids = %v, want []", ids)
574		}
575		if _, found, _ := st.GetInstance("svc", "edge"); found {
576			t.Fatalf("lost record was not deleted")
577		}
578	}
579	
580	func TestHeartbeatRestoresOnlyThatInstance(t *testing.T) {
581		router, st := testRouter(t)
582		registerInstance(t, router, map[string]any{
583			"service_name": "svc", "instance_id": "a", "healthy": true,
584			"weight": 5, "heartbeat_at": at(0),
585		})
586		registerInstance(t, router, map[string]any{
587			"service_name": "svc", "instance_id": "b", "healthy": true,
588			"weight": 8, "heartbeat_at": at(0),
589		})
590	
591		// A new heartbeat for one instance must not revive the other lost one.
592		registerInstance(t, router, map[string]any{
593			"service_name": "svc", "instance_id": "a", "healthy": true,
594			"weight": 5, "heartbeat_at": at(10),
595		})
596		peer, found, err := st.GetInstance("svc", "b")
597		if err != nil || !found {
598			t.Fatalf("peer record missing: found=%v err=%v", found, err)
599		}
600		wantHeartbeat, _ := time.Parse(time.RFC3339, at(0))
601		if !peer.HeartbeatAt.Equal(wantHeartbeat) {
602			t.Fatalf("heartbeat touched another instance: %+v", peer)
603		}
604	
605		out := decodeBody(t, doRequest(t, router, http.MethodGet,
606			"/api/v1/discover?service_name=svc&evaluate_at="+at(10)+"&heartbeat_timeout=1m", nil))
607		if ids := instanceIDs(t, out); len(ids) != 1 || ids[0] != "a" {
608			t.Fatalf("ids = %v, want [a]", ids)
609		}
610		if _, found, _ := st.GetInstance("svc", "b"); found {
611			t.Fatalf("lost peer was not cleaned up")
612		}
613	}
614	
615	func TestRepeatedStateChangesKeepOnlyLatest(t *testing.T) {
616		router, st := testRouter(t)
617		registerInstance(t, router, map[string]any{
618			"service_name": "svc", "instance_id": "a", "healthy": true,
619			"weight": 10, "heartbeat_at": at(9),
620		})
621		registerInstance(t, router, map[string]any{
622			"service_name": "svc", "instance_id": "b", "healthy": true,
623			"weight": 5, "heartbeat_at": at(9),
624		})
625		discover := func() []string {
626			out := decodeBody(t, doRequest(t, router, http.MethodGet,
627				"/api/v1/discover?service_name=svc&evaluate_at="+at(10)+"&heartbeat_timeout=5m", nil))
628			return instanceIDs(t, out)
629		}
630		if ids := discover(); len(ids) != 2 || ids[0] != "a" || ids[1] != "b" {
631			t.Fatalf("initial ids = %v, want [a b]", ids)
632		}
633	
634		// Lowering the weight of the same instance id only changes the order.
635		rec := doRequest(t, router, http.MethodPut, "/api/v1/services/svc/instances/a",
636			map[string]any{"healthy": true, "weight": 1, "heartbeat_at": at(9)})
637		if rec.Code != 200 {
638			t.Fatalf("weight update: %d %s", rec.Code, rec.Body.String())
639		}
640		if list, _ := st.ListInstances("svc"); len(list) != 2 {
641			t.Fatalf("duplicate instance rows: %d", len(list))
642		}
643		if ids := discover(); len(ids) != 2 || ids[0] != "b" || ids[1] != "a" {
644			t.Fatalf("after weight drop ids = %v, want [b a]", ids)
645		}
646	
647		// Toggling health removes the instance from hits; a fresh heartbeat with
648		// healthy=true restores it. Only the latest state survives.
649		rec = doRequest(t, router, http.MethodPut, "/api/v1/services/svc/instances/a",
650			map[string]any{"healthy": false, "weight": 1, "heartbeat_at": at(9)})
651		if rec.Code != 200 {
652			t.Fatalf("health update: %d %s", rec.Code, rec.Body.String())
653		}
654		if ids := discover(); len(ids) != 1 || ids[0] != "b" {
655			t.Fatalf("after unhealthy ids = %v, want [b]", ids)
656		}
657		registerInstance(t, router, map[string]any{
658			"service_name": "svc", "instance_id": "a", "healthy": true,
659			"weight": 1, "heartbeat_at": at(10),
660		})
661		if ids := discover(); len(ids) != 2 || ids[0] != "b" || ids[1] != "a" {
662			t.Fatalf("after heartbeat ids = %v, want [b a]", ids)
663		}
664		if list, _ := st.ListInstances("svc"); len(list) != 2 {
665			t.Fatalf("state changes duplicated rows: %d", len(list))
666		}
667	}
668	
669	func TestDiscoverDeletesOnlyLostRecords(t *testing.T) {
670		router, st := testRouter(t)
671		registerInstance(t, router, map[string]any{
672			"service_name": "svc", "instance_id": "lost", "healthy": true,
673			"weight": 10, "heartbeat_at": at(0),
674		})
675		registerInstance(t, router, map[string]any{
676			"service_name": "svc", "instance_id": "fresh", "healthy": true,
677			"weight": 1, "heartbeat_at": at(9),
678		})
679		registerInstance(t, router, map[string]any{
680			"service_name": "svc", "instance_id": "unhealthy-fresh", "healthy": false,
681			"weight": 5, "heartbeat_at": at(9),
682		})
683	
684		out := decodeBody(t, doRequest(t, router, http.MethodGet,
685			"/api/v1/discover?service_name=svc&evaluate_at="+at(10)+"&heartbeat_timeout=1m", nil))
686		if ids := instanceIDs(t, out); len(ids) != 1 || ids[0] != "fresh" {
687			t.Fatalf("ids = %v, want [fresh]", ids)
688		}
689	
690		// The lost record is deleted by the cleanup; online and unhealthy but
691		// fresh records remain stored and visible through the public list entry.
692		list := decodeBody(t, doRequest(t, router, http.MethodGet,
693			"/api/v1/services/svc/instances", nil))
694		if ids := instanceIDs(t, list); len(ids) != 2 {
695			t.Fatalf("public list after cleanup = %v, want 2 entries", ids)
696		}
697		stored, err := st.ListInstances("svc")
698		if err != nil || len(stored) != 2 {
699			t.Fatalf("storage rows = %d err=%v", len(stored), err)
700		}
701		if _, found, _ := st.GetInstance("svc", "lost"); found {
702			t.Fatalf("lost record still stored")
703		}
704		if _, found, _ := st.GetInstance("svc", "unhealthy-fresh"); !found {
705			t.Fatalf("unhealthy fresh record was removed")
706		}
