323	func (s *Server) handleBatchHeartbeat(c *gin.Context) {
324		bag, apiErr := buildParamBag(c)
325		if apiErr != nil {
326			writeError(c, apiErr)
327			return
328		}
329		serviceName, apiErr := bag.requiredText(serviceNameKeys, "service_name must not be empty")
330		if apiErr != nil {
331			writeError(c, apiErr)
332			return
333		}
334		rawEntries, ok := bag.get([]string{"instances"})
335		if !ok {
336			writeError(c, errInvalidParameter("instances must be a non-empty list"))
337			return
338		}
339		entries, ok := rawEntries.([]any)
340		if !ok || len(entries) == 0 {
341			writeError(c, errInvalidParameter("instances must be a non-empty list"))
342			return
343		}
344		targets := make([]store.HeartbeatTarget, 0, len(entries))
345		seen := make(map[string]struct{}, len(entries))
346		for _, rawEntry := range entries {
347			entry, ok := rawEntry.(map[string]any)
348			if !ok {
349				writeError(c, errInvalidParameter("each instance must be an object"))
350				return
351			}
352			instanceID := strings.TrimSpace(stringValue(entry["instance_id"]))
353			if instanceID == "" {
354				writeError(c, errInvalidParameter("instance_id must not be empty"))
355				return
356			}
357			if _, duplicated := seen[instanceID]; duplicated {
358				writeError(c, errInvalidParameter("instance_id must not be duplicated"))
359				return
360			}
361			heartbeatValue, present := entry["heartbeat_at"]
