// expectCleanError verifies the published error shape: exactly one top-level
// error object with string code and message, and a message that leaks no
// SQL, stack trace or file path.
func expectCleanError(t *testing.T, rec *httptest.ResponseRecorder, entry string, wantStatus int, wantCode string) {
    t.Helper()
    if rec.Code != wantStatus {
        t.Fatalf("%s: status = %d, want %d, body %s", entry, rec.Code, wantStatus, rec.Body.String())
    }
    var out map[string]any
    if err := json.Unmarshal(rec.Body.Bytes(), &out); err != nil {
        t.Fatalf("%s: error body is not JSON: %v", entry, err)
    }
    if len(out) != 1 {
        t.Fatalf("%s: error response keys = %v, want only the top-level error object", entry, keysOf(out))
    }
    errObj, ok := out["error"].(map[string]any)
    if !ok {
        t.Fatalf("%s: missing top-level error object: %v", entry, out)
    }
    code, ok := errObj["code"].(string)
    if !ok || code != wantCode {
        t.Fatalf("%s: error.code = %v, want string %q", entry, errObj["code"], wantCode)
    }
    message, ok := errObj["message"].(string)
    if !ok || message == "" {
        t.Fatalf("%s: error.message = %v, want a non-empty string", entry, errObj["message"])
    }
    for _, leak := range []string{"sql", "SQL", "goroutine", "panic", ".go", "/", "\\", ".db"} {
        if strings.Contains(message, leak) {
            t.Fatalf("%s: error.message %q leaks %q (SQL, stack or file path)", entry, message, leak)
        }
    }
}
